(7474557, 1187608, 114285, '<td valign="top">Stunning! I love the editing and that boat!</td>', 'Stunning! I love the editing and that boat!', '2016-09-19 01:39:55.000000', NULL, 1),
(7474592, 1187477, 163081, '<td valign="top">Spectacular. very cool to include the tourist boat to give a sense of its size. In my top 5 and a 9 from me.</td>', 'Spectacular. very cool to include the tourist boat to give a sense of its size. In my top 5 and a 9 from me.', '2016-09-19 10:12:11.000000', NULL, 1),
(7474633, 1187752, 17850, '<td valign="top">Nice color tones, although it seems a bit over-sharpened in my monitor.<br/>Good luck! (7)</td>', 'Nice color tones, although it seems a bit over-sharpened in my monitor.Good luck! (7)', '2016-09-19 15:28:09.000000', NULL, 1),
(7474634, 1187848, 17850, '<td valign="top">The exposure is perfect and the view impressive, but the perspective needs a slight correction IMHO. It seems tilted upwards from the left to the right side.</td>', 'The exposure is perfect and the view impressive, but the perspective needs a slight correction IMHO. It seems tilted upwards from the left to the right side.', '2016-09-19 15:32:52.000000', NULL, 1),
(7474930, 1187795, 182284, '<td valign="top">I''m giving this a 9. The water and sky colors are great but I think you could have lightened the right side just a little and would have made the whole photo pop.</td>', 'I''m giving this a 9. The water and sky colors are great but I think you could have lightened the right side just a little and would have made the whole photo pop.', '2016-09-21 11:03:27.000000', NULL, 1),
(7474932, 1187833, 182284, '<td valign="top">I really like this view and the whole concept and I give this an 8. I would have cleaned up the shore by removing some of the logs. They are a little distracting.</td>', 'I really like this view and the whole concept and I give this an 8. I would have cleaned up the shore by removing some of the logs. They are a little distracting.', '2016-09-21 11:05:27.000000', NULL, 1),
(7474933, 1187798, 182284, '<td valign="top">I''m really tired of ocean photos. They begin to all look the same even with the contrasting orange. I gave this a 5.</td>', 'I''m really tired of ocean photos. They begin to all look the same even with the contrasting orange. I gave this a 5.', '2016-09-21 11:07:09.000000', NULL, 1),
(7474934, 1187554, 182284, '<td valign="top">This is definitely a 10. I could not think of a thing I would do different. I love this photo. This is one of the nicest I''ve seen. This should  be a winner.</td>', 'This is definitely a 10. I could not think of a thing I would do different. I love this photo. This is one of the nicest I''ve seen. This should  be a winner.', '2016-09-21 11:09:27.000000', NULL, 1),
(7474937, 1187384, 182284, '<td valign="top">I find this one very interesting but I would like to have seen a little more of the right side of the shore. 5</td>', 'I find this one very interesting but I would like to have seen a little more of the right side of the shore. 5', '2016-09-21 11:19:48.000000', NULL, 1),
(7474939, 1187128, 182284, '<td valign="top">The colors are awesome but IMHO its just a little busy for this challenge.</td>', 'The colors are awesome but IMHO its just a little busy for this challenge.', '2016-09-21 11:20:52.000000', NULL, 1),
(7474940, 1187582, 182284, '<td valign="top">A very nice try at this challenge but I think a little less sea and a little more of the foliage would have been much better.5</td>', 'A very nice try at this challenge but I think a little less sea and a little more of the foliage would have been much better.5', '2016-09-21 11:21:07.000000', NULL, 1),
(7474958, 1187410, 182284, '<td valign="top">I love the colors and this photo is great, it should make it to the top 3. If I had done it, I would love to have seen this with the tree closer to the left side of the photo. 8</td>', 'I love the colors and this photo is great, it should make it to the top 3. If I had done it, I would love to have seen this with the tree closer to the left side of the photo. 8', '2016-09-21 11:44:39.000000', NULL, 1),
(7474963, 1187280, 182284, '<td valign="top">Beautiful photo, great composition and color. This really meets the challenge perfectly. I would have removed the sign. 9</td>', 'Beautiful photo, great composition and color. This really meets the challenge perfectly. I would have removed the sign. 9', '2016-09-21 11:53:10.000000', NULL, 1),
(7474964, 1187711, 182284, '<td valign="top">Very nice. I really like the process. 10</td>', 'Very nice. I really like the process. 10', '2016-09-21 11:54:42.000000', NULL, 1),
