(7474996, 1187371, 23484, '<td valign="top">I really like the perspective on this.</td>', 'I really like the perspective on this.', '2016-09-21 14:38:19.000000', NULL, 1),
(7474997, 1187727, 23484, '<td valign="top">The low lighting is beautiful.</td>', 'The low lighting is beautiful.', '2016-09-21 14:38:37.000000', NULL, 1),
(7474999, 1187658, 23484, '<td valign="top">I love the pastel colors.</td>', 'I love the pastel colors.', '2016-09-21 14:39:07.000000', NULL, 1),
(7475000, 1187834, 23484, '<td valign="top">Beautiful point of view and great color tone.</td>', 'Beautiful point of view and great color tone.', '2016-09-21 14:39:44.000000', NULL, 1),
(7475001, 1187410, 23484, '<td valign="top">Nice reflection and wonderful colors.</td>', 'Nice reflection and wonderful colors.', '2016-09-21 14:40:01.000000', NULL, 1),
(7475002, 1187848, 23484, '<td valign="top">Very nice evening view.</td>', 'Very nice evening view.', '2016-09-21 14:40:35.000000', NULL, 1),
(7475003, 1187365, 23484, '<td valign="top">This processing is wonderful. So painterly looking.</td>', 'This processing is wonderful. So painterly looking.', '2016-09-21 14:41:27.000000', NULL, 1),
(7475004, 1187826, 23484, '<td valign="top">Great composition.</td>', 'Great composition.', '2016-09-21 14:42:04.000000', NULL, 1),
(7475005, 1187655, 23484, '<td valign="top">Very cool looking image.</td>', 'Very cool looking image.', '2016-09-21 14:42:38.000000', NULL, 1),
(7475006, 1187802, 23484, '<td valign="top">Outstanding silhouette.  Great light.</td>', 'Outstanding silhouette.  Great light.', '2016-09-21 14:43:23.000000', NULL, 1),
(7475007, 1187321, 23484, '<td valign="top">Well composed and great processing.</td>', 'Well composed and great processing.', '2016-09-21 14:43:58.000000', NULL, 1),
(7475008, 1187565, 23484, '<td valign="top">Love the moon in this.</td>', 'Love the moon in this.', '2016-09-21 14:44:49.000000', NULL, 1),
(7475009, 1187711, 23484, '<td valign="top">This is beautiful. Nice color tone.</td>', 'This is beautiful. Nice color tone.', '2016-09-21 14:46:10.000000', NULL, 1),
(7475019, 1187726, 2612, '<td valign="top">Nicely done! Having a face that close to the edge of the frame and headed out is a little uncomfortable.... I''m assuming that was intentional and appreciate the effort.</td>', 'Nicely done! Having a face that close to the edge of the frame and headed out is a little uncomfortable.... I''m assuming that was intentional and appreciate the effort.', '2016-09-21 17:08:27.000000', NULL, 1),
(7475190, 1187836, 70270, '<td valign="top">Nice forms; would have liked this a whole lot better if you would have cropped it below the tree tops.  6 as is; 8+ cropped.</td>', 'Nice forms; would have liked this a whole lot better if you would have cropped it below the tree tops.  6 as is; 8+ cropped.', '2016-09-22 13:00:21.000000', NULL, 1),
(7475243, 1187711, 101256, '<td valign="top">What a great candid.  Very good post processing - the slightly off tone color is excellent. Well done</td>', 'What a great candid.  Very good post processing - the slightly off tone color is excellent. Well done', '2016-09-22 20:43:13.000000', NULL, 1),
(7475244, 1187797, 101256, '<td valign="top">I took a second look at this and decided I was a little harsh for no real reason. I like the overall concept and execution. Very appropriate. Changed from an 8 to a 10.</td>', 'I took a second look at this and decided I was a little harsh for no real reason. I like the overall concept and execution. Very appropriate. Changed from an 8 to a 10.', '2016-09-22 20:44:30.000000', NULL, 1),
(7475245, 1187720, 101256, '<td valign="top">Wow....amazing detail, evokes a sense of fantasy - there could be a great story built around this image. Excellent.</td>', 'Wow....amazing detail, evokes a sense of fantasy - there could be a great story built around this image. Excellent.', '2016-09-22 20:45:34.000000', NULL, 1),
(7475246, 1187365, 101256, '<td valign="top">I love abstracts - this is terrific in my opinion. A very real appreciation of form without being over done such that you lose a sense of proportion and meaning with respect to the nature of the challenge.</td>', 'I love abstracts - this is terrific in my opinion. A very real appreciation of form without being over done such that you lose a sense of proportion and meaning with respect to the nature of the challenge.', '2016-09-22 20:48:14.000000', NULL, 1),
(7475247, 1187757, 101256, '<td valign="top">I think the HDR is a little overdone, but it''s not so overdone that it detracts from the over all impact of the image. Rich detail and color - a very good entry.</td>', 'I think the HDR is a little overdone, but it''s not so overdone that it detracts from the over all impact of the image. Rich detail and color - a very good entry.', '2016-09-22 20:49:27.000000', NULL, 1),
(7475248, 1187716, 101256, '<td valign="top">Another HDR that is just on the edge of overdone which, frankly, is perfect. A great group candid with difficult lighting conditions. Excellent.</td>', 'Another HDR that is just on the edge of overdone which, frankly, is perfect. A great group candid with difficult lighting conditions. Excellent.', '2016-09-22 20:50:37.000000', NULL, 1),
(7475249, 1187752, 101256, '<td valign="top">I originally rated this a 8 but on review, it deserves a 9. Its a terrific stock shot of commercial quality.</td>', 'I originally rated this a 8 but on review, it deserves a 9. Its a terrific stock shot of commercial quality.', '2016-09-22 20:51:33.000000', NULL, 1),
(7475250, 1187847, 101256, '<td valign="top">I''ve looked at this a couple of times and I can''t help feeling that it is just ever so slightly out of focus. It could have been a ten.</td>', 'I''ve looked at this a couple of times and I can''t help feeling that it is just ever so slightly out of focus. It could have been a ten.', '2016-09-22 20:52:31.000000', NULL, 1),
(7475251, 1187280, 101256, '<td valign="top">Good color control, subject matter is well done - a very good standard image.</td>', 'Good color control, subject matter is well done - a very good standard image.', '2016-09-22 20:53:22.000000', NULL, 1),
(7475253, 1187554, 101256, '<td valign="top">I''m not a fan of the "flowing water" genre of landscape photography as I feel it is often overdone. However in this case, it only enhances the over feeling of ancient time and space.</td>', 'I''m not a fan of the "flowing water" genre of landscape photography as I feel it is often overdone. However in this case, it only enhances the over feeling of ancient time and space.', '2016-09-22 20:59:35.000000', NULL, 1),
(7475254, 1187213, 101256, '<td valign="top">A good standard stock shot - high quality snapshot type image.</td>', 'A good standard stock shot - high quality snapshot type image.', '2016-09-22 21:00:12.000000', NULL, 1),
(7475255, 1187805, 101256, '<td valign="top">I move this from an 8 to a 10 - upon review, I have a very pleasant feeling of peace and tranquility. Excellent.</td>', 'I move this from an 8 to a 10 - upon review, I have a very pleasant feeling of peace and tranquility. Excellent.', '2016-09-22 21:01:26.000000', NULL, 1),
(7475257, 1187806, 101256, '<td valign="top">A little too much single color tones - variations on a theme - do not work all that well.  However there are some positives and the immediate feeling of desolation is palpable.</td>', 'A little too much single color tones - variations on a theme - do not work all that well.  However there are some positives and the immediate feeling of desolation is palpable.', '2016-09-22 21:02:54.000000', NULL, 1),
(7475262, 1187810, 101256, '<td valign="top">I had to look at this three or four times - I can''t quite express what I feel is wrong here. In fairness, it is an interesting shot, but the darker tones in the foreground and distance dissolution of detail don''t peak my interest.</td>', 'I had to look at this three or four times - I can''t quite express what I feel is wrong here. In fairness, it is an interesting shot, but the darker tones in the foreground and distance dissolution of detail don''t peak my interest.', '2016-09-22 21:04:54.000000', NULL, 1),
(7475263, 1187565, 101256, '<td valign="top">I like ship imagery - have quite a collection of different ships myself. I like this, but there isn''t a real hook to it to give it more than a medium rating.</td>', 'I like ship imagery - have quite a collection of different ships myself. I like this, but there isn''t a real hook to it to give it more than a medium rating.', '2016-09-22 21:06:22.000000', NULL, 1),
(7475264, 1187301, 101256, '<td valign="top">Out the window shots are a lot of fun. This is pretty good.</td>', 'Out the window shots are a lot of fun. This is pretty good.', '2016-09-22 21:09:40.000000', NULL, 1),
(7475265, 1187833, 101256, '<td valign="top">In fairness, this looks to me to be slightly out of focus - it could just be me though. It meets the challenge criteria nicely.  I like the jumble of drift wood and the figures on the beach - gives the image some depth.</td>', 'In fairness, this looks to me to be slightly out of focus - it could just be me though. It meets the challenge criteria nicely.  I like the jumble of drift wood and the figures on the beach - gives the image some depth.', '2016-09-22 21:11:32.000000', NULL, 1),
(7475266, 1187749, 101256, '<td valign="top">I really want to say something positive about this, but I can''t find anything on which to hang a comment on. I like it, I just don''t know why I like it. Which, I suppose, is the nature of photography - what one sees, another doesn''t. Worthy of an 8.</td>', 'I really want to say something positive about this, but I can''t find anything on which to hang a comment on. I like it, I just don''t know why I like it. Which, I suppose, is the nature of photography - what one sees, another doesn''t. Worthy of an 8.', '2016-09-22 21:13:47.000000', NULL, 1),
(7475267, 1187809, 101256, '<td valign="top">I feel the color is a little washed out in particular with reference to the sky - perhaps a lighter darker contrast or a B&amp;W conversion where you could work with the different color temperatures to enhance the image.</td>', 'I feel the color is a little washed out in particular with reference to the sky - perhaps a lighter darker contrast or a B&W conversion where you could work with the different color temperatures to enhance the image.', '2016-09-22 21:15:02.000000', NULL, 1),
(7475268, 1187727, 101256, '<td valign="top">A golden hour shot - I like the slightly red over tone lighting - very soft and inviting.</td>', 'A golden hour shot - I like the slightly red over tone lighting - very soft and inviting.', '2016-09-22 21:16:24.000000', NULL, 1),
(7475269, 1187658, 101256, '<td valign="top">Too light - needs a little less exposure or contrast. Sharpening might have helped this a lot.</td>', 'Too light - needs a little less exposure or contrast. Sharpening might have helped this a lot.', '2016-09-22 21:22:27.000000', NULL, 1),
(7475270, 1187655, 101256, '<td valign="top">I love it - on third review, I feel I was a little harsher than necessary in rating the image. Moved from an 8 to a 9. Very nice.</td>', 'I love it - on third review, I feel I was a little harsher than necessary in rating the image. Moved from an 8 to a 9. Very nice.', '2016-09-22 21:23:15.000000', NULL, 1),
(7475271, 1187753, 101256, '<td valign="top">Sometimes you just run into an image that you can''t really discount with a negative, but can''t really say it create a positive response. This is one of those - a very good composition and capture - on third review, moved from an 8 to a 9.</td>', 'Sometimes you just run into an image that you can''t really discount with a negative, but can''t really say it create a positive response. This is one of those - a very good composition and capture - on third review, moved from an 8 to a 9.', '2016-09-22 21:25:37.000000', NULL, 1),
(7475273, 1187407, 101256, '<td valign="top">The top third of this could have been cropped with any negative impact and it would have made this a 9 or 10.</td>', 'The top third of this could have been cropped with any negative impact and it would have made this a 9 or 10.', '2016-09-22 21:32:42.000000', NULL, 1),
(7475274, 1187834, 101256, '<td valign="top">Another example of where a good top crop - say 1/4 off the top - would have improved the image a lot - give it some focus on the subject matter. Still, a nice image.</td>', 'Another example of where a good top crop - say 1/4 off the top - would have improved the image a lot - give it some focus on the subject matter. Still, a nice image.', '2016-09-22 21:33:58.000000', NULL, 1),
(7475275, 1187226, 101256, '<td valign="top">Usually images need a good crop off the top, but in this case, the bottom 25% removed would have really improved this a lot.</td>', 'Usually images need a good crop off the top, but in this case, the bottom 25% removed would have really improved this a lot.', '2016-09-22 21:42:56.000000', NULL, 1),
(7475276, 1187826, 101256, '<td valign="top">I think this has a little DOF issue which creates an "out of focus" effect.</td>', 'I think this has a little DOF issue which creates an "out of focus" effect.', '2016-09-22 21:44:08.000000', NULL, 1),
(7475277, 1187704, 101256, '<td valign="top">Love it - good color, lots of detail and a good impression. Moved from an 8 to a 9 on second review.</td>', 'Love it - good color, lots of detail and a good impression. Moved from an 8 to a 9 on second review.', '2016-09-22 21:45:03.000000', NULL, 1),
(7475278, 1187848, 101256, '<td valign="top">I visited Alanya many years ago - beautiful city which this image brings to life.</td>', 'I visited Alanya many years ago - beautiful city which this image brings to life.', '2016-09-22 21:47:09.000000', NULL, 1),
(7475279, 1187715, 101256, '<td valign="top">On third review, I''m moving this from a 8 to a 10. I''m not a fan of flowing water imagery and I feel that this is way over done, but it has an overall positive impression - I like the B&amp;W conversion which is very good.</td>', 'On third review, I''m moving this from a 8 to a 10. I''m not a fan of flowing water imagery and I feel that this is way over done, but it has an overall positive impression - I like the B&W conversion which is very good.', '2016-09-22 21:48:28.000000', NULL, 1),
(7475280, 1187758, 101256, '<td valign="top">A few minutes earlier with a little more exposure would have made this a terrific image.</td>', 'A few minutes earlier with a little more exposure would have made this a terrific image.', '2016-09-22 21:49:14.000000', NULL, 1),
(7475282, 1187783, 101256, '<td valign="top">At first I didn''t like this - I was overly critical of the foreground, but after looking at it several times, I realized that the overall positive impression was actually due to the excellent DOF control So.....8 to a 10.</td>', 'At first I didn''t like this - I was overly critical of the foreground, but after looking at it several times, I realized that the overall positive impression was actually due to the excellent DOF control So.....8 to a 10.', '2016-09-22 21:50:50.000000', NULL, 1),
