(7475740, 1187410, 97225, '<td valign="top">Beautiful and serene. Lovely light.</td>', 'Beautiful and serene. Lovely light.', '2016-09-26 00:07:00.000000', NULL, 1),
(7475741, 1187802, 94815, '<td valign="top">Good silhouette seashore and well processed.</td>', 'Good silhouette seashore and well processed.', '2016-09-26 00:07:51.000000', NULL, 1),
(7475742, 1187410, 94815, '<td valign="top">Beautiful mirror and such delicious detail.</td>', 'Beautiful mirror and such delicious detail.', '2016-09-26 00:08:44.000000', NULL, 1),
(7475743, 1187783, 97225, '<td valign="top">Lovely entry. Just wondering what the note might say. Looks like it might mention that the ship was on fire.</td>', 'Lovely entry. Just wondering what the note might say. Looks like it might mention that the ship was on fire.', '2016-09-26 00:09:12.000000', NULL, 1),
(7475744, 1187844, 97225, '<td valign="top">Fabulous reflections.</td>', 'Fabulous reflections.', '2016-09-26 00:10:08.000000', NULL, 1),
(7475745, 1187716, 94815, '<td valign="top">Love the dramatic light and shadows and processing that makes it work.</td>', 'Love the dramatic light and shadows and processing that makes it work.', '2016-09-26 00:10:14.000000', NULL, 1),
(7475746, 1187371, 94815, '<td valign="top">Beautiful delta-scape. Gorgeous color.</td>', 'Beautiful delta-scape. Gorgeous color.', '2016-09-26 00:11:12.000000', NULL, 1),
(7475747, 1187720, 94815, '<td valign="top">Beautiful water, atmosphere and mountains.</td>', 'Beautiful water, atmosphere and mountains.', '2016-09-26 00:12:01.000000', NULL, 1),
(7475748, 1187131, 94815, '<td valign="top">This has it all - setting sun, silhouetted lighthouse, water stretching up the beach.</td>', 'This has it all - setting sun, silhouetted lighthouse, water stretching up the beach.', '2016-09-26 00:13:59.000000', NULL, 1),
(7475749, 1187805, 94815, '<td valign="top">Yes indeed. Unique location and pretty too.</td>', 'Yes indeed. Unique location and pretty too.', '2016-09-26 00:19:50.000000', NULL, 1),
(7475750, 1187829, 94815, '<td valign="top">Very dramatic and lovely range of tones. My personal taste is that the blue atmosphere is exaggerated. I always resort to monochrome myself.</td>', 'Very dramatic and lovely range of tones. My personal taste is that the blue atmosphere is exaggerated. I always resort to monochrome myself.', '2016-09-26 00:23:00.000000', NULL, 1),
(7475751, 1187655, 94815, '<td valign="top">Unusual macro look at exceptional seashore effect. Well photographed.</td>', 'Unusual macro look at exceptional seashore effect. Well photographed.', '2016-09-26 00:24:20.000000', NULL, 1),
(7475752, 1187828, 94815, '<td valign="top">Beautiful atmospheric effect.</td>', 'Beautiful atmospheric effect.', '2016-09-26 00:25:36.000000', NULL, 1),
(7475754, 1187844, 100831, '<td valign="top">A stunner. Like cotton candy.</td>', 'A stunner. Like cotton candy.', '2016-09-26 00:30:33.000000', NULL, 1),
(7475755, 1187710, 100831, '<td valign="top">So much to see... Looks good to me...</td>', 'So much to see... Looks good to me...', '2016-09-26 00:31:26.000000', NULL, 1),
(7475756, 1187592, 100831, '<td valign="top">Cute!</td>', 'Cute!', '2016-09-26 00:31:55.000000', NULL, 1),
(7475757, 1187810, 100831, '<td valign="top">That''s impressive/oppressive. And I''ll be back to see where this is.</td>', 'That''s impressive/oppressive. And I''ll be back to see where this is.', '2016-09-26 00:33:29.000000', NULL, 1),
(7475758, 1187088, 100831, '<td valign="top">It just goes on forever. Nice monochrome.</td>', 'It just goes on forever. Nice monochrome.', '2016-09-26 00:34:55.000000', NULL, 1),
(7475759, 1187726, 50695, '<td valign="top">Theater of the absurd<br/> <br/>I''m hanging this in my fantasy art gallery<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1077279" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg"/></a></td>', 'Theater of the absurd I''m hanging this in my fantasy art gallery ', '2016-09-26 00:35:05.000000', NULL, 1),
(7475760, 1187846, 50695, '<td valign="top">well composed</td>', 'well composed', '2016-09-26 00:35:18.000000', NULL, 1),
