INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7475767, 1187699, 100831, '<td valign="top">Great reflection. Golden.</td>', 'Great reflection. Golden.', '2016-09-26 00:40:14.000000', NULL, 1),
(7475772, 1187658, 100831, '<td valign="top">Lovely. I might have cropped some from the top to bring the boards closer to the thirds line, but maybe your crop is better.  I enjoy the smoothness of the blue vs the earthy texture of the shore. 7</td>', 'Lovely. I might have cropped some from the top to bring the boards closer to the thirds line, but maybe your crop is better.  I enjoy the smoothness of the blue vs the earthy texture of the shore. 7', '2016-09-26 00:45:10.000000', NULL, 1),
(7475773, 1187798, 100831, '<td valign="top">Canon beach? Lovely colors and reflection.</td>', 'Canon beach? Lovely colors and reflection.', '2016-09-26 00:46:31.000000', NULL, 1),
(7475774, 1187410, 100831, '<td valign="top">Golden simplicity.</td>', 'Golden simplicity.', '2016-09-26 00:47:00.000000', NULL, 1),
(7475775, 1187828, 100831, '<td valign="top">Pretty.</td>', 'Pretty.', '2016-09-26 00:48:42.000000', NULL, 1),
(7475779, 1187410, 97225, '<td valign="top">Congratulations again, Judi. Beautiful scene. Three blues in row - wonder what the record is?</td>', 'Congratulations again, Judi. Beautiful scene. Three blues in row - wonder what the record is?', '2016-09-26 01:13:57.000000', NULL, 0),
(7475780, 1187749, 97225, '<td valign="top">Congrats on the HM. Beautiful!</td>', 'Congrats on the HM. Beautiful!', '2016-09-26 01:18:06.000000', NULL, 0),
(7475782, 1187716, 97225, '<td valign="top">Congrats on the red. Melethia has properly expressed what I felt about this.</td>', 'Congrats on the red. Melethia has properly expressed what I felt about this.', '2016-09-26 01:21:50.000000', NULL, 0),
(7475783, 1187655, 97225, '<td valign="top">Congrats on the ribbon. Beautiful shot!</td>', 'Congrats on the ribbon. Beautiful shot!', '2016-09-26 01:22:53.000000', NULL, 0),
(7475786, 1187410, 140305, '<td valign="top">Ha! I was wondering if you''d make it 3 in a row and you did! Awesome and congratulations on the blue :)</td>', 'Ha! I was wondering if you''d make it 3 in a row and you did! Awesome and congratulations on the blue :)', '2016-09-26 02:30:25.000000', NULL, 0),
(7475787, 1187716, 140305, '<td valign="top">Congrats Georges, great shot, one of my top picks.</td>', 'Congrats Georges, great shot, one of my top picks.', '2016-09-26 02:31:17.000000', NULL, 0),
(7475788, 1187749, 140305, '<td valign="top">Gorgeous shot Anita, congrats on the HM</td>', 'Gorgeous shot Anita, congrats on the HM', '2016-09-26 02:32:11.000000', NULL, 0),
(7475791, 1187365, 114285, '<td valign="top">Very good stuff!</td>', 'Very good stuff!', '2016-09-26 06:34:24.000000', NULL, 0),
(7475792, 1187716, 124729, '<td valign="top">Congratulation for the ribbon Georges. Nice picture, even if it (IMHO) does not meet the challenge.</td>', 'Congratulation for the ribbon Georges. Nice picture, even if it (IMHO) does not meet the challenge.', '2016-09-26 08:43:18.000000', NULL, 0),
(7475794, 1187410, 163081, '<td valign="top">Congratulations on the 3rd blue in a row :)<br/></td>', 'Congratulations on the 3rd blue in a row :)', '2016-09-26 09:22:47.000000', NULL, 0),
(7475795, 1187846, 109227, '<td valign="top">You were robbed :)</td>', 'You were robbed :)', '2016-09-26 09:23:00.000000', NULL, 0),
(7475798, 1187410, 20608, '<td valign="top">Nice Hatrick</td>', 'Nice Hatrick', '2016-09-26 11:14:55.000000', NULL, 0),
(7475800, 1187834, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>There is a lovely feeling of space with the distant figures on an empty beach for a child full of life to run free who makes a very strong focal point to give the image scale and with his pose a dynamic quality. The waves complete that dynamism together with the lovely shapes the sea has carved out of the beach. Given the dynamics of the beach and sea against the much less interesting sky this is one where I would have used the reverse balance with the beach dominating. I like the near mono/pastel tones. Thanks for another lovely entry Janine</td>', 'Hello from the critique club An appealing image that meets the challenge There is a lovely feeling of space with the distant figures on an empty beach for a child full of life to run free who makes a very strong focal point to give the image scale and with his pose a dynamic quality. The waves complete that dynamism together with the lovely shapes the sea has carved out of the beach. Given the dynamics of the beach and sea against the much less interesting sky this is one where I would have used the reverse balance with the beach dominating. I like the near mono/pastel tones. Thanks for another lovely entry Janine', '2016-09-26 12:25:20.000000', NULL, 0),
(7475801, 1187828, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>Your apt title says it all. There is a lovely mystical quality to this dream-like image where slowly a beautiful mermaid will magically appear. I like the near-abstractness of it all where land merges into mist/sea/sky almost seamlessly with sufficient separation from the band of blue to make the clouds seem like a reflection of the water. Well done in achieving a higher score than you anticipated and for your HM Paschalis.</td>', 'Hello from the critique club An appealing image that meets the challenge Your apt title says it all. There is a lovely mystical quality to this dream-like image where slowly a beautiful mermaid will magically appear. I like the near-abstractness of it all where land merges into mist/sea/sky almost seamlessly with sufficient separation from the band of blue to make the clouds seem like a reflection of the water. Well done in achieving a higher score than you anticipated and for your HM Paschalis.', '2016-09-26 12:34:37.000000', NULL, 0),
(7475802, 1187658, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge<br/> <br/>Your image has a nice balance to it with the distant land and your two figures balancing each other fairly well. Although generally overexposed I think the high key effect works well for the background but not the foreground. You could seriously improve the image by burning in the foreground and making it darker and whilst I normally dislike blown highlights I would leave the rest as is because it actually works well here. Thanks for an interesting entry Jonathon.</td>', 'Hello from the critique club An appealing image that meets the challenge Your image has a nice balance to it with the distant land and your two figures balancing each other fairly well. Although generally overexposed I think the high key effect works well for the background but not the foreground. You could seriously improve the image by burning in the foreground and making it darker and whilst I normally dislike blown highlights I would leave the rest as is because it actually works well here. Thanks for an interesting entry Jonathon.', '2016-09-26 12:43:32.000000', NULL, 0),
(7475803, 1187829, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that meets the challenge<br/> <br/>What a considerate bunch of mates you have, Im not sure I could get away with throwing everybody out of the motor for an image! I have to say, I actually prefer this sort of shot over the long exposure misty scenes that have become so popular nowadays. Your scene is intensely blue rather to its detriment, I think you could say this is an example of an adherence to capture the scene as seen but resulting in a somewhat artificial end result that lacks credibility. Thanks for an interesting entry Eugene.</td>', 'Hello from the critique club An interesting image that meets the challenge What a considerate bunch of mates you have, Im not sure I could get away with throwing everybody out of the motor for an image! I have to say, I actually prefer this sort of shot over the long exposure misty scenes that have become so popular nowadays. Your scene is intensely blue rather to its detriment, I think you could say this is an example of an adherence to capture the scene as seen but resulting in a somewhat artificial end result that lacks credibility. Thanks for an interesting entry Eugene.', '2016-09-26 12:55:10.000000', NULL, 0),
(7475808, 1187810, 29011, '<td valign="top">Made my top5 fave list. Beautiful image. I do like that two people in the capture, wouldn''t have liked the image as much without them. They add to the sense of scale.</td>', 'Made my top5 fave list. Beautiful image. I do like that two people in the capture, wouldn''t have liked the image as much without them. They add to the sense of scale.', '2016-09-26 13:45:13.000000', NULL, 0),
(7475809, 1187749, 12611, '<td valign="top">Beautiful light- and a fitting theme- really well done.</td>', 'Beautiful light- and a fitting theme- really well done.', '2016-09-26 14:00:01.000000', NULL, 0),
(7475810, 1187655, 12611, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2016-09-26 14:02:38.000000', NULL, 0),
(7475811, 1187716, 12611, '<td valign="top">Love the details, story, and the super focal point. Meets the challenge just fine.</td>', 'Love the details, story, and the super focal point. Meets the challenge just fine.', '2016-09-26 14:05:24.000000', NULL, 0),
(7475812, 1187832, 12611, '<td valign="top">This is so much more than what it seems, but people round here are "skin deep."  So much drama is created by the close crop, the tilt and the toxic green. Terrific brown ribbon.</td>', 'This is so much more than what it seems, but people round here are "skin deep."  So much drama is created by the close crop, the tilt and the toxic green. Terrific brown ribbon.', '2016-09-26 14:14:13.000000', NULL, 0),
(7475813, 1187339, 12611, '<td valign="top">I like what you managed to show and not show here- it tells an intimate story.</td>', 'I like what you managed to show and not show here- it tells an intimate story.', '2016-09-26 14:14:49.000000', NULL, 0),
(7475814, 1187819, 12611, '<td valign="top">I like this a great deal- green and purple make such a great contrasting compliment. Perhaps it is a bit subtle for the "photographic intrigue in every picture" crew.</td>', 'I like this a great deal- green and purple make such a great contrasting compliment. Perhaps it is a bit subtle for the "photographic intrigue in every picture" crew.', '2016-09-26 14:16:29.000000', NULL, 0),
(7475815, 1187828, 12611, '<td valign="top">I really like this one, (perhaps the killer central fog was toxic for some folks- because it could have easily been top 3).<br/><br/><i>Message edited by author 2016-09-26 13:22:56.</i></td>', 'I really like this one, (perhaps the killer central fog was toxic for some folks- because it could have easily been top 3).', '2016-09-26 14:19:22.000000', '2016-09-26 14:22:56.000000', 0),
(7475817, 1187720, 12611, '<td valign="top">Fantastic shot Margaret. I love the structure on the left- such a great addition to the shot and perfectly done.</td>', 'Fantastic shot Margaret. I love the structure on the left- such a great addition to the shot and perfectly done.', '2016-09-26 14:26:25.000000', NULL, 0),
(7475818, 1187699, 12611, '<td valign="top">I can imagine the scene from what you show, and that makes it a good accomplishment. Maybe there could be a bit of a more flattering angle to give it the extra "wow factor"- but subtlety is sometimes a casualty of DPC war.</td>', 'I can imagine the scene from what you show, and that makes it a good accomplishment. Maybe there could be a bit of a more flattering angle to give it the extra "wow factor"- but subtlety is sometimes a casualty of DPC war.', '2016-09-26 14:31:06.000000', NULL, 0),
(7475821, 1187809, 67258, '<td valign="top">Perfect!</td>', 'Perfect!', '2016-09-26 14:44:44.000000', NULL, 0),
(7475849, 1187128, 114285, '<td valign="top">It looks like a  lovely place. I''m sure if you tried really hard you could of gotten a very awesome shot</td>', 'It looks like a  lovely place. I''m sure if you tried really hard you could of gotten a very awesome shot', '2016-09-26 21:38:12.000000', NULL, 0),
(7475856, 1187128, 30982, '<td valign="top">I liked this precisely because of Helen.  Without Helen it would be just another tourist shot, but WITH Helen... well, now you have a marvelous story from your trip!</td>', 'I liked this precisely because of Helen.  Without Helen it would be just another tourist shot, but WITH Helen... well, now you have a marvelous story from your trip!', '2016-09-26 23:42:14.000000', NULL, 0),
(7475879, 1187834, 114285, '<td valign="top">Another cute one of your grandson :)</td>', 'Another cute one of your grandson :)', '2016-09-27 08:18:46.000000', NULL, 0),
(7475881, 1187410, 182284, '<td valign="top">Congratulations, I knew this would do well.</td>', 'Congratulations, I knew this would do well.', '2016-09-27 09:55:36.000000', NULL, 0),
(7475966, 1187477, 124815, '<td valign="top">I was one of your three 10s. It is outrageously good. I venture to say one of the best on the subject that I''ve ever seen. Fearless. Welcome back on safe ground Robert!</td>', 'I was one of your three 10s. It is outrageously good. I venture to say one of the best on the subject that I''ve ever seen. Fearless. Welcome back on safe ground Robert!', '2016-09-27 19:16:17.000000', NULL, 0),
(7475967, 1187320, 124815, '<td valign="top">I was your 10 John.</td>', 'I was your 10 John.', '2016-09-27 19:17:40.000000', NULL, 0),
(7475968, 1187582, 124815, '<td valign="top">Splendid. A good end of the world. The Adriatic?<br/></td>', 'Splendid. A good end of the world. The Adriatic?', '2016-09-27 19:20:05.000000', NULL, 0),
(7475969, 1187833, 124815, '<td valign="top">Is this the true name of the Pass? If so,never has been a name so apt. <br/>I love this and the composition is amazing, the parallel lines of the reflection and the tree....the scattered people....</td>', 'Is this the true name of the Pass? If so,never has been a name so apt. I love this and the composition is amazing, the parallel lines of the reflection and the tree....the scattered people....', '2016-09-27 19:23:16.000000', NULL, 0),
(7475970, 1187839, 124815, '<td valign="top">Must say that I loved here the washed colors. And all. How could one find ones wings if color blind? And yet...A superb image</td>', 'Must say that I loved here the washed colors. And all. How could one find ones wings if color blind? And yet...A superb image', '2016-09-27 19:25:55.000000', NULL, 0),
(7476000, 1187726, 123833, '<td valign="top">I don''t get it either</td>', 'I don''t get it either', '2016-09-27 23:55:48.000000', NULL, 0),
(7476260, 1187749, 112739, '<td valign="top">Congrats Anita! For you and your tastes, this image sits in the traditional category pretty firmly. I like it a lot though. Nice mood.</td>', 'Congrats Anita! For you and your tastes, this image sits in the traditional category pretty firmly. I like it a lot though. Nice mood.', '2016-09-29 17:07:39.000000', NULL, 0),
(7476261, 1187477, 112739, '<td valign="top">What, no story to go with this breathtaking image?? I''m very surprised to see the boat navigating that closely to all the floaters.</td>', 'What, no story to go with this breathtaking image?? I''m very surprised to see the boat navigating that closely to all the floaters.', '2016-09-29 17:11:40.000000', NULL, 0),
(7476903, 1187407, 135744, '<td valign="top">Very nice indeed. You have captured a magical moment.</td>', 'Very nice indeed. You have captured a magical moment.', '2016-10-03 12:27:38.000000', NULL, 0),
(7482253, 1187561, 98565, '<td valign="top">For most of the voters it wasn''t spectacular enough I guess. Maybe now - after voting is over - there is a great advantage when watching this picture - it is shown bigger at least on my monitor. That is why I didn''t see water at all when I opened this site, it revealed slowly when I scrolled down. And there it was -  kind of a surprise.<br/> <br/>I like it! That the dog walker''s sweater is the same blue is an additional bonus</td>', 'For most of the voters it wasn''t spectacular enough I guess. Maybe now - after voting is over - there is a great advantage when watching this picture - it is shown bigger at least on my monitor. That is why I didn''t see water at all when I opened this site, it revealed slowly when I scrolled down. And there it was -  kind of a surprise. I like it! That the dog walker''s sweater is the same blue is an additional bonus', '2016-11-13 07:56:08.000000', NULL, 0),
(7482278, 1187561, 138630, '<td valign="top">Thank you, Teafran and Barbara.  Lovely comments.  It was what it was - and is what it is.  Not spectacular but somehow satisfying, I think, and that''s often enough for me :)</td>', 'Thank you, Teafran and Barbara.  Lovely comments.  It was what it was - and is what it is.  Not spectacular but somehow satisfying, I think, and that''s often enough for me :)', '2016-11-13 10:46:59.000000', NULL, 0);
COMMIT;
